            if grid[r][c] != bg:
                points.setdefault(grid[r][c], []).append((r, c))

    for color, pts in points.items():
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if dr and abs(dr) == abs(dc):
                    sr = 1 if dr > 0 else -1
                    sc = 1 if dc > 0 else -1
                    # Extend away from both ends of the diagonal pair,
                    # stopping at other existing colored cells.
                    for r, c, vr, vc in (
                        (r1 - sr, c1 - sc, -sr, -sc),
                        (r2 + sr, c2 + sc, sr, sc),
                    ):
                        while 0 <= r < h and 0 <= c < w:
                            if out[r][c] != bg:
                                break
                            out[r][c] = color
                            r += vr
                            c += vc
                    break
    return out
